import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_bf16_3x3(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_out,
    .param .u32 param_total
)
{
    .reg .pred %p;
    .reg .b16 %h_in, %h_w, %h_out;
    .reg .u32 %r_total, %r_tid, %r_ntid, %r_ctaid, %r_nctaid;
    .reg .u32 %r_idx, %r_stride, %r_tmp;
    .reg .u32 %r_n, %r_oc, %r_oh, %r_ow;
    .reg .u32 %r_ic, %r_kh, %r_kw;
    .reg .u32 %r_base_in, %r_base_w, %r_off;
    .reg .u64 %rd_in, %rd_w, %rd_out, %rd_addr;
    .reg .f32 %f_acc, %f_in, %f_w;

    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_out, [param_out];
    ld.param.u32 %r_total, [param_total];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_nctaid, %nctaid.x;

    mad.lo.u32 %r_idx, %r_ctaid, %r_ntid, %r_tid;
    mul.lo.u32 %r_stride, %r_nctaid, %r_ntid;

GRID_LOOP:
    setp.ge.u32 %p, %r_idx, %r_total;
    @%p bra GRID_DONE;

    // decompose idx -> (n, oc, oh, ow) with oc=32, oh/ow in [0,222)
    rem.u32 %r_ow, %r_idx, 222;
    div.u32 %r_tmp, %r_idx, 222;
    rem.u32 %r_oh, %r_tmp, 222;
    div.u32 %r_tmp, %r_tmp, 222;
    rem.u32 %r_oc, %r_tmp, 32;
    div.u32 %r_n, %r_tmp, 32;

    // base input offset: n*150528 + oh*224 + ow  (150528 = 3*224*224)
    mul.lo.u32 %r_base_in, %r_n, 150528;
    mad.lo.u32 %r_base_in, %r_oh, 224, %r_base_in;
    add.u32 %r_base_in, %r_base_in, %r_ow;

    // base weight offset: oc*27  (27 = 3*3*3)
    mul.lo.u32 %r_base_w, %r_oc, 27;

    mov.f32 %f_acc, 0f00000000;
    mov.u32 %r_ic, 0;
IC_LOOP:
    setp.ge.u32 %p, %r_ic, 3;
    @%p bra IC_DONE;
    mov.u32 %r_kh, 0;
KH_LOOP:
    setp.ge.u32 %p, %r_kh, 3;
    @%p bra KH_DONE;
    mov.u32 %r_kw, 0;
KW_LOOP:
    setp.ge.u32 %p, %r_kw, 3;
    @%p bra KW_DONE;

    // input offset += ic*50176 + kh*224 + kw  (50176 = 224*224)
    mad.lo.u32 %r_off, %r_ic, 50176, %r_base_in;
    mad.lo.u32 %r_off, %r_kh, 224, %r_off;
    add.u32 %r_off, %r_off, %r_kw;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_in, %rd_addr;
    ld.global.b16 %h_in, [%rd_addr];
    cvt.f32.bf16 %f_in, %h_in;

    // weight offset += ic*9 + kh*3 + kw
    mad.lo.u32 %r_off, %r_ic, 9, %r_base_w;
    mad.lo.u32 %r_off, %r_kh, 3, %r_off;
    add.u32 %r_off, %r_off, %r_kw;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_w, %rd_addr;
    ld.global.b16 %h_w, [%rd_addr];
    cvt.f32.bf16 %f_w, %h_w;

    fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;

    add.u32 %r_kw, %r_kw, 1;
    bra KW_LOOP;
KW_DONE:
    add.u32 %r_kh, %r_kh, 1;
    bra KH_LOOP;
KH_DONE:
    add.u32 %r_ic, %r_ic, 1;
    bra IC_LOOP;
IC_DONE:

    cvt.rn.bf16.f32 %h_out, %f_acc;
    mul.wide.u32 %rd_addr, %r_idx, 2;
    add.u64 %rd_addr, %rd_out, %rd_addr;
    st.global.b16 [%rd_addr], %h_out;

    add.u32 %r_idx, %r_idx, %r_stride;
    bra GRID_LOOP;
GRID_DONE:
    ret;
}
